-- IO CLI (io-harness store): ~/.io-cli/runs.db (only the tables used for the join)
CREATE TABLE runs (id INTEGER PRIMARY KEY AUTOINCREMENT, goal TEXT NOT NULL, file TEXT NOT NULL, outcome TEXT, provider TEXT, parent_run_id INTEGER, depth INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'running', started_at TEXT, turn_kind TEXT);
CREATE TABLE provider_calls (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL, step INTEGER NOT NULL, attempt INTEGER NOT NULL, provider TEXT NOT NULL, model TEXT, prompt_tokens INTEGER, completion_tokens INTEGER, total_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, reasoning_tokens INTEGER, server_tool_requests INTEGER, latency_ms INTEGER NOT NULL, ttft_ms INTEGER, finish_reason TEXT, failure TEXT, at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE mcp_events (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL, step INTEGER NOT NULL, kind TEXT NOT NULL, server TEXT NOT NULL, tool TEXT, ok INTEGER, millis INTEGER, detail TEXT);
CREATE TABLE tool_attempts (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL, step INTEGER NOT NULL, tool TEXT NOT NULL, started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), completed_at TEXT, resolution TEXT);
CREATE TABLE step_turns (run_id INTEGER NOT NULL, step INTEGER NOT NULL, text TEXT, calls TEXT NOT NULL, PRIMARY KEY (run_id, step));
